package com.example.microsave.loan.entity;
import com.example.microsave.member.entity.Member; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate;
@Entity @Table(name="loans") public class Loan {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="member_id",nullable=false)private Member member;@Column(nullable=false,precision=12,scale=2)private BigDecimal amount;@Column(nullable=false)private LocalDate loanDate;@Column(nullable=false,precision=12,scale=2)private BigDecimal outstandingAmount;@Column(nullable=false,length=20)private String status;@Column(length=300)private String purpose;public Loan(){}public Long getId(){return id;}public Member getMember(){return member;}public void setMember(Member v){member=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public LocalDate getLoanDate(){return loanDate;}public void setLoanDate(LocalDate v){loanDate=v;}public BigDecimal getOutstandingAmount(){return outstandingAmount;}public void setOutstandingAmount(BigDecimal v){outstandingAmount=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getPurpose(){return purpose;}public void setPurpose(String v){purpose=v;}}
